import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.CqzWVxDX.js";const b=JSON.parse('{"title":"GOOSE 接收、DataSet 历史与抓包链路重构","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/iec61850/goose/04-receive-history-capture-refactoring.md","filePath":"changelog/iec61850/goose/04-receive-history-capture-refactoring.md","lastUpdated":1783855034000}'),n={name:"changelog/iec61850/goose/04-receive-history-capture-refactoring.md"};function l(d,e,r,o,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="goose-接收、dataset-历史与抓包链路重构" tabindex="-1">GOOSE 接收、DataSet 历史与抓包链路重构 <a class="header-anchor" href="#goose-接收、dataset-历史与抓包链路重构" aria-label="Permalink to &quot;GOOSE 接收、DataSet 历史与抓包链路重构&quot;">​</a></h1><blockquote><p>日期：2026-07-12<br> 状态：已实现<br> 范围：Windows GOOSE 接收、ASN.1 BER 解析、DataSet 元数据映射、历史缓存、抓包 WebSocket、前端交互与日志分级</p></blockquote><h2 id="_1-背景与问题边界" tabindex="-1">1. 背景与问题边界 <a class="header-anchor" href="#_1-背景与问题边界" aria-label="Permalink to &quot;1. 背景与问题边界&quot;">​</a></h2><p>测试服务端已经使能 GOOSE，Wireshark 能稳定捕获 EtherType <code>0x88B8</code> 报文，但应用出现以下症状：</p><ul><li>Receiver 显示“启动成功”，当前 GOOSE 数据和历史数据仍为空。</li><li>抓包页面无法收到数据，停止按钮状态也不可靠。</li><li>DataSet 表格只能显示 <code>Entry[0]</code>、<code>Entry[1]</code>，无法显示真实 FCDA 引用。</li><li>GOOSE 高频重传后，“前值”迅速被覆盖成“当前值”。</li><li>历史页签每次轮询都重新加载整批数据，选中行会丢失。</li><li>Windows 首次加载 Scapy/Npcap 时可能被 0.5 秒启动超时误判为失败。</li></ul><p>这些问题横跨二层收包、BER 解码、模型关联、缓存语义和前端状态机，不能通过单独修改页面文案解决。</p><h2 id="_2-现场证据与根因" tabindex="-1">2. 现场证据与根因 <a class="header-anchor" href="#_2-现场证据与根因" aria-label="Permalink to &quot;2. 现场证据与根因&quot;">​</a></h2><h3 id="_2-1-报文确实到达目标网卡" tabindex="-1">2.1 报文确实到达目标网卡 <a class="header-anchor" href="#_2-1-报文确实到达目标网卡" aria-label="Permalink to &quot;2.1 报文确实到达目标网卡&quot;">​</a></h3><p>在 WLAN 上直接捕获到的关键字段为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EtherType  = 0x88B8</span></span>
<span class="line"><span>APPID      = 0x0001</span></span>
<span class="line"><span>goCbRef    = PCS01PIGO/LLN0$GO$gocb0</span></span>
<span class="line"><span>datSet     = PCS01PIGO/LLN0$dsGOOSE0</span></span>
<span class="line"><span>confRev    = 1</span></span>
<span class="line"><span>numEntries = 10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>数据库中的启用订阅具有相同 <code>goCbRef</code> 和 APPID。因此问题不在服务端发送，也不在订阅过滤条件。</p><h3 id="_2-2-windows-libiec61850-receiver-未触发回调" tabindex="-1">2.2 Windows libiec61850 Receiver 未触发回调 <a class="header-anchor" href="#_2-2-windows-libiec61850-receiver-未触发回调" aria-label="Permalink to &quot;2.2 Windows libiec61850 Receiver 未触发回调&quot;">​</a></h3><p>原实现直接调用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GooseReceiver_create</span></span>
<span class="line"><span>GooseReceiver_setInterfaceId</span></span>
<span class="line"><span>GooseReceiver_addSubscriber</span></span>
<span class="line"><span>GooseReceiver_start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>底层返回运行状态，但在 Windows/Npcap 环境没有触发 Python 回调。将友好网卡名替换为 <code>\\Device\\NPF_{GUID}</code> 后仍无回调，因此不能简单归因于网卡名称转换。</p><p>最终策略是：</p><ul><li>Windows Receiver 使用已验证可靠的 Scapy/Npcap 捕获路径。</li><li>Linux/macOS 保留 libiec61850/原始套接字路径。</li><li>两条路径最终写入同一 <code>GooseSubscriptionInfo</code> 状态模型。</li></ul><h3 id="_2-3-goose-ber-标签定义错误" tabindex="-1">2.3 GOOSE BER 标签定义错误 <a class="header-anchor" href="#_2-3-goose-ber-标签定义错误" aria-label="Permalink to &quot;2.3 GOOSE BER 标签定义错误&quot;">​</a></h3><p>旧抓包解析器使用了错误或整体偏移的标签。现场报文显示实际标签如下：</p><table tabindex="0"><thead><tr><th>字段</th><th style="text-align:right;">正确标签</th></tr></thead><tbody><tr><td>GOOSE PDU</td><td style="text-align:right;"><code>0x61</code></td></tr><tr><td>goCbRef</td><td style="text-align:right;"><code>0x80</code></td></tr><tr><td>timeAllowedToLive</td><td style="text-align:right;"><code>0x81</code></td></tr><tr><td>datSet</td><td style="text-align:right;"><code>0x82</code></td></tr><tr><td>goID</td><td style="text-align:right;"><code>0x83</code></td></tr><tr><td>timestamp</td><td style="text-align:right;"><code>0x84</code></td></tr><tr><td>stNum</td><td style="text-align:right;"><code>0x85</code></td></tr><tr><td>sqNum</td><td style="text-align:right;"><code>0x86</code></td></tr><tr><td>test/simulation</td><td style="text-align:right;"><code>0x87</code></td></tr><tr><td>confRev</td><td style="text-align:right;"><code>0x88</code></td></tr><tr><td>ndsCom</td><td style="text-align:right;"><code>0x89</code></td></tr><tr><td>numDatSetEntries</td><td style="text-align:right;"><code>0x8A</code></td></tr><tr><td>allData</td><td style="text-align:right;"><code>0xAB</code></td></tr></tbody></table><p>旧实现期待 PDU <code>0xA1</code>、allData <code>0x8A</code>，导致报文虽被抓到，却无法进入 DataSet 解码。</p><h3 id="_2-4-mms-data-标签与浮点编码处理错误" tabindex="-1">2.4 MMS Data 标签与浮点编码处理错误 <a class="header-anchor" href="#_2-4-mms-data-标签与浮点编码处理错误" aria-label="Permalink to &quot;2.4 MMS Data 标签与浮点编码处理错误&quot;">​</a></h3><p>GOOSE <code>allData</code> 中使用 MMS 上下文标签：</p><table tabindex="0"><thead><tr><th>类型</th><th style="text-align:right;">标签</th><th>解码</th></tr></thead><tbody><tr><td>boolean</td><td style="text-align:right;"><code>0x83</code></td><td>非零为 <code>true</code></td></tr><tr><td>bit-string</td><td style="text-align:right;"><code>0x84</code></td><td>跳过 unused-bits 字节后合并</td></tr><tr><td>integer</td><td style="text-align:right;"><code>0x85</code></td><td>BER 整数</td></tr><tr><td>unsigned</td><td style="text-align:right;"><code>0x86</code></td><td>BER 无符号整数</td></tr><tr><td>floating-point</td><td style="text-align:right;"><code>0x87</code></td><td>指数宽度前缀 + IEEE-754 数据</td></tr><tr><td>octet-string</td><td style="text-align:right;"><code>0x89</code></td><td>十六进制字符串</td></tr><tr><td>visible-string</td><td style="text-align:right;"><code>0x8A</code></td><td>UTF-8/可见字符串</td></tr><tr><td>utc-time</td><td style="text-align:right;"><code>0x91</code></td><td>UTC 时间字节</td></tr></tbody></table><p>浮点值通常编码为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>87 05 08 XX XX XX XX</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中 <code>08</code> 是指数宽度描述，后 4 字节才是 float32。旧实现从 <code>08</code> 开始直接解包，得到错误结果。</p><h2 id="_3-接收架构调整" tabindex="-1">3. 接收架构调整 <a class="header-anchor" href="#_3-接收架构调整" aria-label="Permalink to &quot;3. 接收架构调整&quot;">​</a></h2><h3 id="_3-1-统一数据流" tabindex="-1">3.1 统一数据流 <a class="header-anchor" href="#_3-1-统一数据流" aria-label="Permalink to &quot;3.1 统一数据流&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant NIC as 网卡/Npcap</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CAP as GooseCaptureEngine</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant SUB as GooseReceiver</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant STATE as GooseSubscriptionInfo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as Receiver 状态 API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant UI as 前端</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NIC-&gt;&gt;CAP: Ethernet 0x88B8 frame</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CAP-&gt;&gt;CAP: VLAN + GOOSE Header + BER 解码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CAP-&gt;&gt;SUB: CapturedPacket</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SUB-&gt;&gt;SUB: goCbRef / APPID / MAC 过滤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SUB-&gt;&gt;STATE: 更新 stNum、sqNum、DataSet 值</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SUB-&gt;&gt;STATE: 写入历史 deque(maxlen=200)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UI-&gt;&gt;API: 轻量轮询 Receiver 状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;UI: message_count / history_count / 当前值</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UI-&gt;&gt;API: revision 变化时请求历史</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;UI: 最近 200 条历史</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h3 id="_3-2-windows-npcap-启动" tabindex="-1">3.2 Windows Npcap 启动 <a class="header-anchor" href="#_3-2-windows-npcap-启动" aria-label="Permalink to &quot;3.2 Windows Npcap 启动&quot;">​</a></h3><p>Windows 分支创建 <code>GooseCaptureEngine</code>，注册 <code>_on_captured_packet</code> 回调，并在捕获线程真正就绪后才把 Receiver 标记为运行。</p><p>首次导入 Scapy 和枚举 Npcap 适配器可能明显超过 0.5 秒，因此启动等待策略调整为：</p><table tabindex="0"><thead><tr><th>平台</th><th style="text-align:right;">启动等待</th></tr></thead><tbody><tr><td>Windows</td><td style="text-align:right;">5 秒</td></tr><tr><td>Linux/macOS</td><td style="text-align:right;">0.5 秒</td></tr></tbody></table><p>这个等待是“最大就绪等待”，线程提前就绪会立即返回，不会固定阻塞 5 秒。</p><h3 id="_3-3-生命周期" tabindex="-1">3.3 生命周期 <a class="header-anchor" href="#_3-3-生命周期" aria-label="Permalink to &quot;3.3 生命周期&quot;">​</a></h3><p>停止 Receiver 时必须按以下顺序清理：</p><ol><li>设置 Receiver 非运行状态。</li><li>停止超时监控线程。</li><li>从捕获引擎移除回调，避免停止阶段继续写状态。</li><li>停止 Npcap 捕获线程。</li><li>释放 libiec61850 Subscriber/Handler（非 Windows 路径）。</li><li>将订阅状态恢复为 <code>init</code>。</li></ol><h2 id="_4-dataset-值与引用映射" tabindex="-1">4. DataSet 值与引用映射 <a class="header-anchor" href="#_4-dataset-值与引用映射" aria-label="Permalink to &quot;4. DataSet 值与引用映射&quot;">​</a></h2><h3 id="_4-1-为什么报文里只有-entry-i" tabindex="-1">4.1 为什么报文里只有 <code>Entry[i]</code> <a class="header-anchor" href="#_4-1-为什么报文里只有-entry-i" aria-label="Permalink to &quot;4.1 为什么报文里只有 \`Entry[i]\`&quot;">​</a></h3><p>GOOSE 报文的 <code>allData</code> 只携带有序值，不携带每个值对应的 FCDA 引用。正确解释必须依赖同一个 DataSet 的成员目录：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allData[0] &lt;-&gt; DataSet.members[0]</span></span>
<span class="line"><span>allData[1] &lt;-&gt; DataSet.members[1]</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>因此 <code>Entry[0]</code> 不是协议返回的名称，而是元数据缺失时的保底显示。</p><h3 id="_4-2-三层元数据来源" tabindex="-1">4.2 三层元数据来源 <a class="header-anchor" href="#_4-2-三层元数据来源" aria-label="Permalink to &quot;4.2 三层元数据来源&quot;">​</a></h3><p>DataSet 成员按以下优先级解析：</p><ol><li><strong>订阅已持久化的 <code>dataset_entries</code></strong>：避免重复查询。</li><li><strong>MMS DataSet Directory 在线读取</strong>：复用 Reports 的目录读取能力。</li><li><strong>IEC 61850 模型缓存</strong>：在线读取返回 <code>object-non-existent</code> 时回退。</li></ol><h3 id="_4-3-与-引用规范化" tabindex="-1">4.3 <code>$</code> 与 <code>.</code> 引用规范化 <a class="header-anchor" href="#_4-3-与-引用规范化" aria-label="Permalink to &quot;4.3 \`$\` 与 \`.\` 引用规范化&quot;">​</a></h3><p>现场存在两种等价引用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报文/GOOSE 配置：PCS01PIGO/LLN0$dsGOOSE0</span></span>
<span class="line"><span>模型缓存：       PCS01PIGO/LLN0.dsGOOSE0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>匹配时统一规范为点号形式，再比较完整引用。模型缓存命中后得到 10 个成员，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 -&gt; PCS01PIGO/GGIO1.AnIn1.mag.i  FC=MX  integer</span></span>
<span class="line"><span>1 -&gt; PCS01PIGO/GGIO1.AnIn2.mag.f  FC=MX  float</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>9 -&gt; PCS01PIGO/GGIO2.AnIn5.mag.f  FC=MX  float</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>解析到的成员会写回 Subscription 并持久化。当前值和已存在的历史条目也会重新应用元数据，不必等待下一次值变化才看到真实引用。</p><h2 id="_5-前值、当前值与重传语义" tabindex="-1">5. 前值、当前值与重传语义 <a class="header-anchor" href="#_5-前值、当前值与重传语义" aria-label="Permalink to &quot;5. 前值、当前值与重传语义&quot;">​</a></h2><h3 id="_5-1-错误实现" tabindex="-1">5.1 错误实现 <a class="header-anchor" href="#_5-1-错误实现" aria-label="Permalink to &quot;5.1 错误实现&quot;">​</a></h3><p>旧逻辑把“上一帧的值”作为前值：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 -&gt; 45 -&gt; 45 -&gt; 45</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>第一次变化时显示 <code>0 / 45</code>，但下一次重传后就变成 <code>45 / 45</code>。这不符合用户对变化历史的理解。</p><h3 id="_5-2-正确实现" tabindex="-1">5.2 正确实现 <a class="header-anchor" href="#_5-2-正确实现" aria-label="Permalink to &quot;5.2 正确实现&quot;">​</a></h3><p>现在定义为：</p><ul><li><strong>当前值</strong>：最新报文值。</li><li><strong>前值</strong>：最近一次与当前值不同的历史值。</li><li><strong>changed</strong>：本次报文是否使值发生变化。</li><li><strong>changed_at</strong>：本次变化时间；重复报文不产生新的变化时间。</li></ul><p>状态转换示例：</p><table tabindex="0"><thead><tr><th>输入序列</th><th style="text-align:right;">前值</th><th style="text-align:right;">当前值</th><th>changed</th></tr></thead><tbody><tr><td>首次 <code>0</code></td><td style="text-align:right;">空</td><td style="text-align:right;">0</td><td>false</td></tr><tr><td>重传 <code>0</code></td><td style="text-align:right;">空</td><td style="text-align:right;">0</td><td>false</td></tr><tr><td>变化 <code>45</code></td><td style="text-align:right;">0</td><td style="text-align:right;">45</td><td>true</td></tr><tr><td>重传 <code>45</code></td><td style="text-align:right;">0</td><td style="text-align:right;">45</td><td>false</td></tr><tr><td>变化 <code>12</code></td><td style="text-align:right;">45</td><td style="text-align:right;">12</td><td>true</td></tr></tbody></table><p>Windows Npcap 和 libiec61850 两条接收路径使用相同语义。</p><h2 id="_6-历史环形队列与性能" tabindex="-1">6. 历史环形队列与性能 <a class="header-anchor" href="#_6-历史环形队列与性能" aria-label="Permalink to &quot;6. 历史环形队列与性能&quot;">​</a></h2><h3 id="_6-1-有界历史" tabindex="-1">6.1 有界历史 <a class="header-anchor" href="#_6-1-有界历史" aria-label="Permalink to &quot;6.1 有界历史&quot;">​</a></h3><p>每个 <code>goCbRef</code> 对应一个：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deque(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">maxlen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>达到 200 条后，新增记录自动淘汰最旧记录，不会因 GOOSE 高频重传导致内存无限增长。</p><p>历史项保存：</p><ul><li><code>received_at</code></li><li>GOOSE timestamp</li><li><code>st_num</code> / <code>sq_num</code></li><li><code>conf_rev</code></li><li><code>data_set_ref</code></li><li><code>value_count</code> / <code>changed_count</code></li><li>当次 DataSet 值快照</li></ul><h3 id="_6-2-页签计数与正文解耦" tabindex="-1">6.2 页签计数与正文解耦 <a class="header-anchor" href="#_6-2-页签计数与正文解耦" aria-label="Permalink to &quot;6.2 页签计数与正文解耦&quot;">​</a></h3><p>后端状态增加：</p><ul><li><code>message_count</code>：累计接收 revision，持续增长。</li><li><code>history_count</code>：当前环形队列内条数，最大 200。</li></ul><p>前端页签数字使用 <code>history_count</code>，因此停留在“属性配置”或“最近 GOOSE 数据”时仍会变化。</p><p>历史正文不再每 2 秒无条件拉取：</p><ol><li>状态轮询取得 <code>message_count</code>。</li><li>与 <code>historyKnownRevision</code> 比较。</li><li>revision 未变化则跳过历史请求。</li><li>revision 变化且历史页可见时，最多请求 200 条。</li></ol><h3 id="_6-3-过期响应与选中行稳定性" tabindex="-1">6.3 过期响应与选中行稳定性 <a class="header-anchor" href="#_6-3-过期响应与选中行稳定性" aria-label="Permalink to &quot;6.3 过期响应与选中行稳定性&quot;">​</a></h3><p>前端使用单调递增 <code>historyRequestId</code> 丢弃过期请求，避免快速切换控制块时旧响应覆盖新选择。</p><p>历史表使用 <code>received_at</code> 作为稳定 <code>row-key</code>，并通过 <code>current-row-key</code> 恢复当前行。替换轮询数据时 Element Plus 可能短暂发出 <code>null</code> 选中事件，该事件被忽略，因此用户查看的行和详情不会被定时刷新清除。</p><h2 id="_7-抓包-websocket-修复" tabindex="-1">7. 抓包 WebSocket 修复 <a class="header-anchor" href="#_7-抓包-websocket-修复" aria-label="Permalink to &quot;7. 抓包 WebSocket 修复&quot;">​</a></h2><h3 id="_7-1-根因" tabindex="-1">7.1 根因 <a class="header-anchor" href="#_7-1-根因" aria-label="Permalink to &quot;7.1 根因&quot;">​</a></h3><p>HTTP API 使用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VUE_APP_API_BASE=http://127.0.0.1:8991</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>旧 WebSocket 实现尝试读取未注册的 <code>window.__axios_instance</code>，失败后回退到页面 origin。在开发环境中，这会连接前端端口而不是后端端口。</p><p>同时前端在发送 start 命令前就把 <code>captureRunning</code> 设置为 <code>true</code>，即使 WebSocket 未连接，也会显示正在运行，造成“抓不到且停不掉”的假状态。</p><h3 id="_7-2-修复" tabindex="-1">7.2 修复 <a class="header-anchor" href="#_7-2-修复" aria-label="Permalink to &quot;7.2 修复&quot;">​</a></h3><ul><li>WebSocket 和 HTTP 统一使用 <code>VUE_APP_API_BASE</code>。</li><li>相对地址通过 <code>new URL(..., window.location.origin)</code> 解析。</li><li>只有收到后端 start 成功响应后才设置 <code>captureRunning=true</code>。</li><li>stop 可取消启动中状态。</li><li>后端 stop 先移除回调，再发送非阻塞停止信号，避免 join 阻塞事件循环和响应发送。</li></ul><h3 id="_7-3-抓包与-receiver-的关系" tabindex="-1">7.3 抓包与 Receiver 的关系 <a class="header-anchor" href="#_7-3-抓包与-receiver-的关系" aria-label="Permalink to &quot;7.3 抓包与 Receiver 的关系&quot;">​</a></h3><p>Receiver 和抓包页都可以监听同一网卡，但用途不同：</p><table tabindex="0"><thead><tr><th>能力</th><th>Receiver</th><th>抓包页</th></tr></thead><tbody><tr><td>数据过滤</td><td>按订阅 goCbRef/APPID/MAC</td><td>可选 APPID，默认全部</td></tr><tr><td>输出</td><td>当前值、状态、历史</td><td>原始帧、统计、十六进制</td></tr><tr><td>生命周期</td><td>随订阅启停</td><td>用户显式启停</td></tr><tr><td>数据语义</td><td>DataSet 业务数据</td><td>协议诊断数据</td></tr></tbody></table><h2 id="_8-前端交互整理" tabindex="-1">8. 前端交互整理 <a class="header-anchor" href="#_8-前端交互整理" aria-label="Permalink to &quot;8. 前端交互整理&quot;">​</a></h2><h3 id="_8-1-页面语义" tabindex="-1">8.1 页面语义 <a class="header-anchor" href="#_8-1-页面语义" aria-label="Permalink to &quot;8.1 页面语义&quot;">​</a></h3><ul><li>“最近 GOOSE 数据”展示当前 DataSet 值，不把业务值误称为原始报文。</li><li>“GOOSE 数据历史”展示环形队列中的 DataSet 快照。</li><li>独立“GOOSE 抓包”页面才展示 Ethernet/GOOSE 原始报文。</li></ul><h3 id="_8-2-dataset-表格" tabindex="-1">8.2 DataSet 表格 <a class="header-anchor" href="#_8-2-dataset-表格" aria-label="Permalink to &quot;8.2 DataSet 表格&quot;">​</a></h3><p>保留扁平 DataSet 明细表，字段为：</p><ul><li>数据引用</li><li>描述</li><li>FC</li><li>类型</li><li>前值</li><li>当前值</li></ul><p>表头、行高、边框、背景色、悬停色和字体与 Reports 数据表保持一致。</p><h3 id="_8-3-抓包工具栏" tabindex="-1">8.3 抓包工具栏 <a class="header-anchor" href="#_8-3-抓包工具栏" aria-label="Permalink to &quot;8.3 抓包工具栏&quot;">​</a></h3><ul><li>网卡下拉展示显示名称和 MAC。</li><li>缓存默认 100。</li><li>APPID 默认 1。</li><li>缓存与 APPID 使用左减右加的数字控件。</li><li>控件具有一致高度和响应式换行，不在窄窗口中裁切。</li></ul><h2 id="_9-日志和错误等级" tabindex="-1">9. 日志和错误等级 <a class="header-anchor" href="#_9-日志和错误等级" aria-label="Permalink to &quot;9. 日志和错误等级&quot;">​</a></h2><p>远端 GoEna 写入失败属于服务端操作失败：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设置远端 GoCB GoEna 失败: MMS 连接不可用</span></span>
<span class="line"><span>业务异常: 远端 GOOSE 控制块 GoEna 使能失败 (code=500)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两类日志均使用 <code>ERROR</code>：</p><ul><li><code>client_control.py</code> 的底层失败为 <code>ERROR</code>。</li><li>Web 层 <code>BizError.http_status &gt;= 500</code> 为 <code>ERROR</code>。</li><li>400、404、409 等用户输入或资源状态问题继续使用 <code>WARNING</code>。</li></ul><h2 id="_10-api-与状态字段" tabindex="-1">10. API 与状态字段 <a class="header-anchor" href="#_10-api-与状态字段" aria-label="Permalink to &quot;10. API 与状态字段&quot;">​</a></h2><h3 id="receiver-subscription-状态新增字段" tabindex="-1">Receiver/Subscription 状态新增字段 <a class="header-anchor" href="#receiver-subscription-状态新增字段" aria-label="Permalink to &quot;Receiver/Subscription 状态新增字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>含义</th></tr></thead><tbody><tr><td><code>message_count</code></td><td>integer</td><td>累计接收报文数/revision</td></tr><tr><td><code>history_count</code></td><td>integer</td><td>当前环形队列条数，最大 200</td></tr></tbody></table><h3 id="历史查询" tabindex="-1">历史查询 <a class="header-anchor" href="#历史查询" aria-label="Permalink to &quot;历史查询&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/channels/goose/receivers/subscriptions/history</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>请求上限调整为 200，与环形队列容量一致。</p><h3 id="抓包-websocket" tabindex="-1">抓包 WebSocket <a class="header-anchor" href="#抓包-websocket" aria-label="Permalink to &quot;抓包 WebSocket&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WS /api/channels/goose/capture/ws</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>支持命令：</p><ul><li><code>start</code></li><li><code>stop</code></li><li><code>clear</code></li><li><code>list</code></li><li><code>status</code></li></ul><h2 id="_11-验证结果" tabindex="-1">11. 验证结果 <a class="header-anchor" href="#_11-验证结果" aria-label="Permalink to &quot;11. 验证结果&quot;">​</a></h2><p>本次实现采用三层验证：</p><h3 id="_11-1-现场协议验证" tabindex="-1">11.1 现场协议验证 <a class="header-anchor" href="#_11-1-现场协议验证" aria-label="Permalink to &quot;11.1 现场协议验证&quot;">​</a></h3><ul><li>WLAN 直接捕获到持续发送的 GOOSE 报文。</li><li>APPID 和 goCbRef 与订阅完全一致。</li><li>修复 BER 标签后，3 秒内连续收到 6 条更新。</li><li>每条成功解析 10 个 DataSet 值。</li><li>独立 HTTP 抓包会话可以启动、列出报文并停止。</li></ul><h3 id="_11-2-自动测试" tabindex="-1">11.2 自动测试 <a class="header-anchor" href="#_11-2-自动测试" aria-label="Permalink to &quot;11.2 自动测试&quot;">​</a></h3><ul><li>GOOSE 捕获与订阅测试通过。</li><li>MAC 规范化测试通过。</li><li>设备作用域与持久化测试通过。</li><li>新增重传测试验证：相同值重传不覆盖最近一次不同前值。</li></ul><h3 id="_11-3-静态检查" tabindex="-1">11.3 静态检查 <a class="header-anchor" href="#_11-3-静态检查" aria-label="Permalink to &quot;11.3 静态检查&quot;">​</a></h3><ul><li>Ruff lint 通过。</li><li>Ruff format 检查通过。</li><li>Vue/TypeScript 类型检查通过。</li><li><code>git diff --check</code> 通过。</li></ul><h2 id="_12-运维排障手册" tabindex="-1">12. 运维排障手册 <a class="header-anchor" href="#_12-运维排障手册" aria-label="Permalink to &quot;12. 运维排障手册&quot;">​</a></h2><h3 id="_12-1-wireshark-有报文-receiver-没数据" tabindex="-1">12.1 Wireshark 有报文，Receiver 没数据 <a class="header-anchor" href="#_12-1-wireshark-有报文-receiver-没数据" aria-label="Permalink to &quot;12.1 Wireshark 有报文，Receiver 没数据&quot;">​</a></h3><p>依次检查：</p><ol><li>Wireshark 是否使用和 Receiver 相同的网卡。</li><li>EtherType 是否为 <code>0x88B8</code>。</li><li>Receiver 是否显示 Npcap 启动成功。</li><li>Subscription 是否启用。</li><li><code>goCbRef</code> 是否完整一致，包括大小写和 <code>$GO$</code>。</li><li>APPID 是否一致。</li><li>配置目标 MAC 时是否与报文一致。</li></ol><p>Windows 关键日志：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GOOSE 报文捕获已启动: interface=...</span></span>
<span class="line"><span>GOOSE Receiver 已启动 (Npcap): interface=..., 订阅数=...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_12-2-显示-entry-n" tabindex="-1">12.2 显示 Entry[n] <a class="header-anchor" href="#_12-2-显示-entry-n" aria-label="Permalink to &quot;12.2 显示 Entry[n]&quot;">​</a></h3><p>检查：</p><ol><li>Subscription 的 <code>dataset_entries</code> 是否为空。</li><li><code>data_set_ref</code> 是否为报文中的完整引用。</li><li>在线 DataSet Directory 是否返回 <code>object-non-existent</code>。</li><li>模型缓存是否包含等价点号引用。</li><li>日志是否出现：</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从模型缓存关联 GOOSE DataSet 成员: ref=..., count=...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_12-3-抓包无法停止" tabindex="-1">12.3 抓包无法停止 <a class="header-anchor" href="#_12-3-抓包无法停止" aria-label="Permalink to &quot;12.3 抓包无法停止&quot;">​</a></h3><p>检查浏览器 WebSocket 是否连接：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ws://&lt;backend&gt;/api/channels/goose/capture/ws</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不要以按钮视觉状态判断后端状态，应调用 status 或查看 start/stop 响应。</p><h3 id="_12-4-goena-失败" tabindex="-1">12.4 GoEna 失败 <a class="header-anchor" href="#_12-4-goena-失败" aria-label="Permalink to &quot;12.4 GoEna 失败&quot;">​</a></h3><p>GoEna 是 MMS 控制操作。即使 GOOSE 二层报文仍在发送，MMS 连接不可用时也会失败。检查设备连接状态、远端 GoCB 引用候选格式和 IED 返回错误码。</p><h2 id="_13-后续建议" tabindex="-1">13. 后续建议 <a class="header-anchor" href="#_13-后续建议" aria-label="Permalink to &quot;13. 后续建议&quot;">​</a></h2><ol><li>抽取 libiec61850 与 Npcap 两条接收路径共用的 DataSet 状态合并函数，继续减少重复逻辑。</li><li>为 BER 解析增加更多结构体、quality、timestamp 和嵌套 array 测试向量。</li><li>在 Receiver 状态中增加最近源 MAC、目标 MAC、VLAN 和 parse error，提升诊断能力。</li><li>将模型缓存 DataSet 查找下沉为统一服务，供 Reports、GOOSE 和 DataSet 页面共同调用。</li><li>为 WebSocket 增加命令 request id，使多个页面同时控制抓包时响应归属更明确。</li></ol>`,140)])])}const u=a(n,[["render",l]]);export{b as __pageData,u as default};
